                        :value="lang">
                        {{ key }}
                    </option>
                </select>
            </a>
        </MenubarItem>
    </MenubarSub>
</template>
<script>
export default {
    computed: {
        workspaces() {
            return this.$storex.projects.projectApps.reduce((acc, app) => {
                const apps = acc[app.workspaceName] || []
                apps.push(app)
                return {
                    ...acc,
                    [app.workspaceName]: apps
                }
            }, {})
        }
    },
    methods: {
        toggleViewMode() {
            if (this.$storex.ui.viewMode === 'vibe') {
                this.$storex.ui.setExpertMode()
            } else {
                this.$storex.ui.setVibeMode()
            }
        },
        toggleAppPanel(app) {
            app = this.$ui.openApps[app.key] || app
            this.$ui.showApp({
                ...app,
                left: !app?.left,
                ts: new Date().getTime()
            })
        },
        showEruda() {
            window.eruda.init()
        }
    }
}
</script>
