          <span class="text-sm text-base-content/60">Connecting to workspace...</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    workspace: { type: Object, default: null },
    app: { type: Object, default: null },
  },
  data() {
    return {
      loading: true,
    }
  },
  mounted() {
    // Give the iframe a moment before hiding spinner
    setTimeout(() => { this.loading = false }, 2000)
  },
  computed: {
    appUrl() {
      if (!this.app) return null
      // Support explicit url, port-based url, or vnc path
      if (this.app.url) return this.app.url
      if (this.app.port) {
        const host = window.location.hostname
        return `http://${host}:${this.app.port}`
      }
      return null
    }
  },
  watch: {
    app() {
      this.loading = true
      setTimeout(() => { this.loading = false }, 2000)
    }
  },
  methods: {}
}
</script>
